html:
{#-
	Manav Quotation: print format of Quotation Head, laid out like the old system's quotation
	(FMT: QUOT-11).

	Working, top to bottom:
	1. Letter head of the quotation (the principal's header), then the title.
	2. Header box: customer name, address and "Kind Attn" on the left; document number, date,
	   customer reference, sales engineer and Cust ID on the right.
	3. Items: each item with its code, description and price. Under the item its specification
	   lines in two columns (a line marked Bold is printed bold), then the options of that item
	   with their prices.
	4. Totals: printed only when the quotation carries freight or a tax amount, because the old
	   machine quotations show prices only and leave taxes to the terms.
	5. Terms and conditions, then the signing employee and the footer line.

	The names of the signing employee and the sales engineer are read from Employee Master by the
	codes stored on the quotation, so the old quotations (which hold only the codes) print them too.

	Created: 2026-10-12.
-#}
{%- macro money(value) -%}{{ "%.2f"|format(value or 0) }}{%- endmacro -%}
{%- macro employee(code) -%}
	{%- set emp = frappe.db.get_value("Employee Master", code, ["employee_name", "designation"], as_dict=True) if code else None -%}
	{{- emp.employee_name if emp else (code or "") -}}
{%- endmacro -%}
{%- set signer = frappe.db.get_value("Employee Master", doc.signature_one_code, ["employee_name", "designation"], as_dict=True) if doc.signature_one_code else None -%}
{%- set signer_name = doc.signed_by_name or (signer.employee_name if signer else (doc.signature_one_code or "")) -%}
{%- set sales_engineer = doc.sales_engineer_name or employee(doc.signature_two_code) -%}
{%- set currency = doc.currency or "" -%}
{#- old quotations have no Haas Cust ID of their own; it is then read from the customer -#}
{%- set cust_id = doc.haas_customer_id or (frappe.db.get_value("Customer", doc.customer, "custom_haas_customer_id") if doc.customer else "") -%}
{%- set item_codes = doc.get("items") | map(attribute="item_code") | list -%}

<style>
	.mq { font-family: Arial, Helvetica, sans-serif; font-size: 9.5pt; color: #000; line-height: 1.35; }
	.mq table { width: 100%; border-collapse: collapse; }
	/* Frappe's print style forces 6px padding on every cell and a margin on every paragraph;
	   the !important rules below take that back so the rows sit close together. */
	.print-format .mq td, .print-format .mq th { padding: 2px 4px !important; vertical-align: top; line-height: 1.35; }
	.mq .title { text-align: center; font-family: "Times New Roman", serif; font-size: 14pt; font-weight: bold; margin: 4px 0; }
	.mq .box { border: 1px solid #000; }
	.mq .box > tbody > tr > td { border: 1px solid #000; }
	.mq .serif { font-family: "Times New Roman", serif; font-weight: bold; font-size: 11pt; }
	.mq .head th { border: 1px solid #000; font-family: "Times New Roman", serif; font-size: 11pt; text-align: center; }
	.mq .right { text-align: right; }
	.mq .small { font-size: 8pt; }
	.mq .options td { border: 1px solid #000; }
	.mq .section { border: 1px solid #000; border-top: 0; padding: 3px 6px; }
	.mq .caps { font-weight: bold; font-size: 8.5pt; }
	.mq .item { page-break-inside: avoid; }
	.print-format .mq .terms td { padding: 1px 4px !important; }
</style>

<div class="mq">
	{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
	<div class="title">Quotation</div>

	<table class="box">
		<tr>
			<td style="width: 50%;">
				<div class="serif">To</div>
				<div class="serif">{{ doc.customer_name or doc.customer or "" }}</div>
				{% for line in [doc.address_1, doc.address_2, doc.address_3] %}{% if line %}<div>{{ line }}</div>{% endif %}{% endfor %}
				<div>{{ doc.city or "" }} &nbsp;&nbsp; {{ doc.pin or "" }}</div>
				<div style="margin-top: 6px;"><b>Kind Attn :</b> &nbsp; {{ doc.contact_person or "" }} &nbsp;{{ doc.designation or "" }}</div>
			</td>
			<td style="width: 50%;">
				<table>
					<tr><td class="serif" style="width: 38%;">Document No.</td><td style="width: 4%;">:</td><td>{{ doc.name }}</td></tr>
					<tr><td class="serif">Date</td><td>:</td><td>{{ frappe.utils.formatdate(doc.quotation_date, "dd/mm/yy") if doc.quotation_date else "" }}</td></tr>
					<tr><td class="serif">Ref. No.</td><td>:</td><td>{{ doc.your_reference or "" }}</td></tr>
					<tr><td class="serif">Ref Dt.</td><td>:</td><td>{{ frappe.utils.formatdate(doc.your_reference_date, "dd/mm/yy") if doc.your_reference_date else "" }}</td></tr>
					<tr><td class="serif">Sales Engg.</td><td>:</td><td>{{ sales_engineer }}</td></tr>
					<tr><td class="serif">Cust ID</td><td>:</td><td>{{ cust_id or "" }}</td></tr>
				</table>
			</td>
		</tr>
	</table>

	{% if doc.message_line_1 or doc.message_line_2 %}
	<div class="section">
		{% if doc.message_line_1 %}<div>{{ doc.message_line_1 }}</div>{% endif %}
		{% if doc.message_line_2 %}<div>{{ doc.message_line_2 }}</div>{% endif %}
	</div>
	{% endif %}

	<table class="head" style="margin-top: -1px;">
		<tr>
			<th style="width: 8%;">Sr.No</th>
			<th style="width: 14%;">Item Code</th>
			<th>Particulars</th>
			<th style="width: 18%;">Price in {{ currency }}</th>
		</tr>
	</table>

	{% for item in doc.get("items") %}
	<div class="section">
		<table class="item">
			<tr>
				<td style="width: 8%;" class="right">{{ "%02d"|format(loop.index) }}</td>
				<td style="width: 14%;" class="serif">{{ item.item_code or "" }}</td>
				<td class="serif">{{ (item.item_description or "") | replace("\n", "<br>") }}
					{%- if frappe.utils.flt(item.qty) != 1 %} &nbsp; ({{ item.qty | round(2) }} {{ item.uom or "" }} x {{ money(item.rate) }}){% endif %}</td>
			</tr>
		</table>

		{# specification lines of this item, laid out across two columns like the old print #}
		{% set specs = doc.specifications | selectattr("item_code", "equalto", item.item_code) | list %}
		{% if specs %}
		<table style="margin: 4px 0 4px 6%; width: 94%;">
			{% for pair in specs | batch(2) %}
			<tr>
				{% for spec in pair %}
				<td style="width: 3%;">*</td>
				<td style="width: 47%;">{% if spec.highlight %}<b>{{ spec.specification or "" }}</b>{% else %}{{ spec.specification or "" }}{% endif %}</td>
				{% endfor %}
				{% if pair | length == 1 %}<td style="width: 3%;"></td><td style="width: 47%;"></td>{% endif %}
			</tr>
			{% endfor %}
		</table>
		{% endif %}

		<table>
			<tr>
				<td style="padding-left: 8%;"><b>Price :</b></td>
				<td class="right" style="width: 10%;"><b>{{ currency }}</b></td>
				<td class="right" style="width: 18%;"><b>{{ money(item.amount) }}</b></td>
			</tr>
		</table>
	</div>

	{# options chosen for this item #}
	{% set options = doc.sub_items | selectattr("main_item_code", "equalto", item.item_code) | list %}
	{% if options %}
	<div class="section" style="padding: 0;">
		<div class="serif" style="padding: 1px 0 1px 12%;">Options</div>
		<table class="options">
			{% for option in options %}
			<tr>
				<td style="width: 6%;" class="right">{{ loop.index }}</td>
				<td style="width: 16%;" class="small">{{ option.sub_item_code or "" }}</td>
				<td>{{ (option.item_description or "") | replace("\n", "<br>") }}</td>
				<td style="width: 18%;" class="right">{{ money(option.amount) }}</td>
			</tr>
			{% endfor %}
		</table>
	</div>
	{% endif %}
	{% endfor %}

	{# options whose main item is not among the items of the quotation #}
	{% set other_options = doc.sub_items | rejectattr("main_item_code", "in", item_codes) | list %}
	{% if other_options %}
	<div class="section" style="padding: 0;">
		<div class="serif" style="padding: 1px 0 1px 12%;">Options</div>
		<table class="options">
			{% for option in other_options %}
			<tr>
				<td style="width: 6%;" class="right">{{ loop.index }}</td>
				<td style="width: 16%;" class="small">{{ option.sub_item_code or "" }}</td>
				<td>{{ (option.item_description or "") | replace("\n", "<br>") }}</td>
				<td style="width: 18%;" class="right">{{ money(option.amount) }}</td>
			</tr>
			{% endfor %}
		</table>
	</div>
	{% endif %}

	{# totals only when there is freight or tax to show #}
	{% if frappe.utils.flt(doc.freight) or frappe.utils.flt(doc.sales_tax_amount) or frappe.utils.flt(doc.sc_on_sales_tax_amount) or frappe.utils.flt(doc.sc_on_taxable_amount) %}
	<div class="section">
		<table>
			<tr><td class="right"><b>Total</b></td><td class="right" style="width: 18%;">{{ money(doc.quotation_amount) }}</td></tr>
			{% if frappe.utils.flt(doc.sales_tax_amount) %}<tr><td class="right">Sales Tax / CGST @ {{ doc.sales_tax_percent | round(2) }}%</td><td class="right">{{ money(doc.sales_tax_amount) }}</td></tr>{% endif %}
			{% if frappe.utils.flt(doc.sc_on_sales_tax_amount) %}<tr><td class="right">SGST @ {{ doc.sc_on_sales_tax_percent | round(2) }}%</td><td class="right">{{ money(doc.sc_on_sales_tax_amount) }}</td></tr>{% endif %}
			{% if frappe.utils.flt(doc.sc_on_taxable_amount) %}<tr><td class="right">IGST @ {{ doc.sc_on_taxable_percent | round(2) }}%</td><td class="right">{{ money(doc.sc_on_taxable_amount) }}</td></tr>{% endif %}
			{% if frappe.utils.flt(doc.freight) %}<tr><td class="right">Freight</td><td class="right">{{ money(doc.freight) }}</td></tr>{% endif %}
			<tr><td class="right"><b>Final Amount ({{ currency }})</b></td><td class="right"><b>{{ money(doc.final_amount) }}</b></td></tr>
		</table>
	</div>
	{% endif %}

	{% if doc.terms %}
	<div class="section">
		<div class="caps">TERMS AND CONDITIONS</div>
		<table class="terms">
			{% for term in doc.terms %}
			<tr>
				{# a second line of the same term (Sr No above 1 with no heading) continues without a number #}
				<td style="width: 5%;" class="right">{{ term.term_type if term.term_desc or term.sr_no in (None, 0, 1) else "" }}</td>
				<td style="width: 32%;">{{ term.term_desc or "" }}</td>
				<td>{{ (term.description or "") | replace("\n", "<br>") }}</td>
			</tr>
			{% endfor %}
		</table>
	</div>
	{% endif %}

	<div class="section" style="page-break-inside: avoid;">
		<div class="caps">For Manav Marketing Pvt. Ltd.</div>
		<div style="height: 42px;"></div>
		<div>{{ signer_name }}</div>
		<div>{{ signer.designation if signer and signer.designation else "" }}</div>
	</div>
	<table class="box" style="margin-top: -1px;">
		<tr>
			<td style="width: 14%;" class="small">FMT: QUOT-11</td>
			<td class="small">CC : &nbsp;{{ sales_engineer }}</td>
			<td style="width: 28%;" class="small right">E &amp; O.E</td>
		</tr>
	</table>
</div>
